customCss:
.wb-addon-notice-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 14px 22px;
  border-radius: var(--radius-lg, 14px);
  margin: 12px 0;
  transition: all 0.3s ease;
  box-sizing: border-box;
}
.wb-addon-notice-banner.surface-glass {
  backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 0.14);
}
.wb-addon-notice-banner.surface-solid {
  background: var(--bg-card, #131b2e);
  border: 1px solid var(--border-subtle, rgba(255,255,255,0.08));
}
.wb-addon-notice-banner.tone-promo {
  background: linear-gradient(135deg, rgba(99, 102, 241, 0.22) 0%, rgba(236, 72, 153, 0.18) 100%);
  border-color: rgba(168, 85, 247, 0.4);
  box-shadow: 0 10px 30px -10px rgba(99, 102, 241, 0.3);
}
.wb-addon-notice-banner.tone-info {
  background: rgba(14, 165, 233, 0.15);
  border-color: rgba(14, 165, 233, 0.4);
}
.wb-addon-notice-banner.tone-success {
  background: rgba(34, 197, 94, 0.15);
  border-color: rgba(34, 197, 94, 0.4);
}
.wb-addon-notice-banner.tone-warning {
  background: rgba(245, 158, 11, 0.15);
  border-color: rgba(245, 158, 11, 0.4);
}
.wb-notice-content {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  font-size: 0.92rem;
  color: #f8fafc;
}
.wb-notice-badge {
  display: inline-flex;
  align-items: center;
  padding: 3px 10px;
  border-radius: 9999px;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  background: #6366f1;
  color: #ffffff;
  text-transform: uppercase;
}
.tone-promo .wb-notice-badge {
  background: linear-gradient(135deg, #6366f1, #ec4899);
}
.wb-notice-msg {
  font-weight: 500;
  line-height: 1.4;
}
.wb-notice-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 6px 14px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.15);
  color: #ffffff;
  font-size: 0.82rem;
  font-weight: 600;
  text-decoration: none;
  border: 1px solid rgba(255, 255, 255, 0.25);
  transition: all 0.2s ease;
}
.wb-notice-btn:hover {
  background: #ffffff;
  color: #0f172a;
  transform: translateY(-1px);
}
.wb-notice-close {
  background: none;
  border: none;
  color: var(--text-dim, #94a3b8);
  font-size: 1.3rem;
  cursor: pointer;
  padding: 4px 8px;
  line-height: 1;
  border-radius: 6px;
  transition: all 0.2s ease;
}
.wb-notice-close:hover {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.1);
}

.wb-addon-timeline {
  padding: 30px 20px;
  max-width: 1100px;
  margin: 0 auto;
}
.wb-timeline-header {
  text-align: center;
  margin-bottom: 36px;
}
.wb-timeline-title {
  font-size: 1.8rem;
  font-weight: 800;
  color: #ffffff;
  margin: 0 0 8px 0;
}
.wb-timeline-sub {
  font-size: 0.95rem;
  color: var(--text-muted, #94a3b8);
  margin: 0;
}
.wb-timeline-steps {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 20px;
  position: relative;
}
.wb-timeline-step-card {
  position: relative;
  background: rgba(19, 27, 46, 0.7);
  backdrop-filter: blur(14px);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 16px;
  padding: 26px 22px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}
.wb-timeline-step-card:hover {
  transform: translateY(-4px);
  border-color: var(--timeline-accent, #6366f1);
  box-shadow: 0 16px 36px -12px rgba(99, 102, 241, 0.35);
}
.wb-timeline-num-badge {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: var(--timeline-accent, #6366f1);
  color: #ffffff;
  font-size: 1.2rem;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 6px 16px -4px var(--timeline-accent, #6366f1);
}
.wb-timeline-step-title {
  font-size: 1.1rem;
  font-weight: 700;
  color: #ffffff;
  margin: 0 0 6px 0;
}
.wb-timeline-step-desc {
  font-size: 0.88rem;
  line-height: 1.55;
  color: var(--text-dim, #94a3b8);
  margin: 0;
}
